#!/usr/bin/env python3
"""Rebuilds src/sws_primer.inc, the frozen Tier 4 primer (ported from HCE Ultra v4).

The primer is 256 KiB: CPython 3.11 standard-library code and C headers (PSF License),
self-authored structured-format samples (structured.py), and licence texts that permit
verbatim copying. See NOTICE.md. The output must match the pinned CRC32C in v4.cpp;
any change to the bytes is a new primer and a v4 format change.

Usage: make_primer.py [--python-root /usr/lib/python3.11] [--include-root /usr/include/python3.11]
                      [--licenses /usr/share/common-licenses] [--bin primer.bin]
"""
import argparse, os, subprocess, sys

PYTHON = ["textwrap.py", "string.py", "shlex.py", "queue.py", "heapq.py", "pprint.py", "tempfile.py", "shutil.py",
          "pathlib.py", "logging/__init__.py", "urllib/parse.py", "threading.py", "subprocess.py", "zipfile.py", "inspect.py"]
HEADERS = ["object.h", "abstract.h", "listobject.h", "dictobject.h", "unicodeobject.h", "pyerrors.h", "longobject.h", "pystate.h",
           "import.h", "modsupport.h", "methodobject.h", "descrobject.h", "sliceobject.h", "fileutils.h", "pymem.h", "pyport.h"]
LICENSES = ["Apache-2.0", "MPL-2.0", "GPL-3", "LGPL-2.1", "Artistic", "BSD", "CC0-1.0"]
K = 1024
LAYOUT = [("python", 112 * K), ("headers", 56 * K), ("structured", 24 * K), ("licenses", 64 * K)]

def read_all(root, names):
    return b"".join(open(os.path.join(root, n), "rb").read() for n in names)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--python-root", default="/usr/lib/python3.11")
    ap.add_argument("--include-root", default="/usr/include/python3.11")
    ap.add_argument("--licenses", default="/usr/share/common-licenses")
    ap.add_argument("--bin", help="also write the raw primer bytes here")
    args = ap.parse_args()
    here = os.path.dirname(os.path.abspath(__file__))
    parts = {
        "python": read_all(args.python_root, PYTHON),
        "headers": read_all(args.include_root, [h for h in HEADERS if os.path.exists(os.path.join(args.include_root, h))]),
        "structured": subprocess.run([sys.executable, "-I", os.path.join(here, "structured.py")], check=True, capture_output=True).stdout,
        "licenses": b"".join(open(os.path.join(args.licenses, n), "rb").read() + b"\n" for n in LICENSES),
    }
    data = b"".join(parts[name][:size] for name, size in LAYOUT)
    if args.bin:
        open(args.bin, "wb").write(data)
    lines = [",".join(str(b) for b in data[i:i + 32]) + "," for i in range(0, len(data), 32)]
    out = os.path.join(here, "..", "..", "src", "sws_primer.inc")
    with open(out, "w") as f:
        f.write("// Generated by third_party/sws_primer/make_primer.py. Do not edit: the bytes are part of the Tier 4 format.\n")
        f.write("\n".join(lines) + "\n")
    print(f"{len(data)} bytes -> {os.path.normpath(out)}")

if __name__ == "__main__":
    main()
